#[inline]
pub fn lil_free(mut lil: lil_t) { unsafe {
    if lil.is_null() {
        return;
    }

    let lilp = &mut *lil;

    free(lilp.err_msg as *mut c_void);
    lil_free_value(lilp.empty);

    let mut env = lilp.env;
    while !env.is_null() {
        let next = (*env).parent as lil_env_t;
        lil_free_env(env);
        env = next;
    }

    let cmd = lilp.cmd;
    let cmds = lilp.cmds;
    let mut i: size_t = 0;
    while i < cmds {
        let func = *cmd.add(i);
        if !(*func).argnames.is_null() {
            lil_free_list((*func).argnames);
        }
        lil_free_value((*func).code);
        free((*func).name as *mut c_void);
        free(func as *mut c_void);
        i = i.wrapping_add(1);
    }

    hm_destroy(&raw mut lilp.cmdmap);
    free(cmd as *mut c_void);
    free(lilp.dollarprefix as *mut c_void);
    free(lilp.catcher as *mut c_void);
    free(lil as *mut c_void);
} }

